			FROM memo child
			JOIN memo_relation rel ON rel.memo_id = child.id AND rel.type = 'COMMENT'
			JOIN memo_tree parent ON rel.related_memo_id = parent.id
		)
		SELECT id, uid
		FROM memo_tree
	`, userID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	memos := make([]deleteUserMemoRef, 0)
	for rows.Next() {
