python3 << 'PYEOF'
import os, re, subprocess
from collections import defaultdict

root = "/bench/repo/internal"
# Find all func declarations in internal (non-test)
decls = []  # (symbol, path, line)
for dirpath, _, files in os.walk(root):
    for f in files:
        if not f.endswith('.go') or f.endswith('_test.go'):
            continue
        path = os.path.join(dirpath, f)
        with open(path) as fh:
            for i, line in enumerate(fh, 1):
                m = re.match(r'^func (?:\([^)]+\) )?(\w+)\(', line)
                if m:
                    decls.append((m.group(1), path, i))

# Count references across repo (excluding internal definition file for same symbol? 
# fan-in = callers elsewhere - typically count all call sites excluding the definition)
# Search each symbol - can have collisions; use package-aware search later

# Get package name for each file
pkg_map = {}
for path in set(d[1] for d in decls):
    with open(path) as fh:
        for line in fh:
            if line.startswith('package '):
                pkg_map[path] = line.split()[1]
                break

# Build unique symbols with package path for disambiguation
from pathlib import Path

# Run ripgrep/grep for each - too many. Better: parse all go files for calls.

call_counts = defaultdict(int)  # (pkg, symbol) -> count
call_sites = defaultdict(set)

# Read all non-test go files in repo
all_files = []
for dirpath, _, files in os.walk('/bench/repo'):
    if 'node_modules' in dirpath or '/.git/' in dirpath:
        continue
    for f in files:
        if f.endswith('.go') and not f.endswith('_test.go'):
            all_files.append(os.path.join(dirpath, f))

# Map symbol -> list of (pkg, path) declarations
sym_decls = defaultdict(list)
for sym, path, line in decls:
    pkg = pkg_map.get(path, '')
    sym_decls[sym].append((pkg, path, line))

# For each file, count identifier calls - rough: word boundary symbol(
for fpath in all_files:
    try:
        content = open(fpath).read()
    except:
        continue
    for sym in sym_decls:
        # count sym( but not in comments - rough
        pattern = r'\b' + re.escape(sym) + r'\s*\('
        matches = len(re.findall(pattern, content))
        if matches:
            for pkg, dpath, line in sym_decls[sym]:
                # attribute calls to each decl if same name - problematic for duplicates
                call_sites[(pkg, sym, dpath)].add(fpath)

# Better approach: use go/ast or count imports + qualified calls
print(f"Total internal funcs: {len(decls)}")
print(f"Symbols with any calls: {len(call_sites)}")

# Sort by fan-in (unique caller files)
ranked = sorted(((len(sites), pkg, sym, dpath) for (pkg, sym, dpath), sites in call_sites.items()), reverse=True)
for fanin, pkg, sym, dpath in ranked[:30]:
    rel = dpath.replace('/bench/repo/', '')
    print(f"{fanin}\t{pkg}.{sym}\t{rel}")
PYEOF

