for my $dir ("$root/internal") {
  opendir my $dh, $dir or die $!;
  my @files;
  find_files($dir, \@files);
  for my $path (@files) {
    next unless $path =~ /\.go$/ && $path !~ /_test\.go$/;
    open my $fh, "<", $path or next;
    my ($pkg, $import);
    my @lines = <$fh>;
    close $fh;
    for (@lines) {
      $pkg = $1 if /^package (\w+)/;
    }
    # derive import path from file path
    (my $rel = $path) =~ s|^\Q$root/\E||;
    my $import_path = "github.com/usememos/memos/$rel";
    $import_path =~ s|/[^/]+$||;

    for my $i (0..$#lines) {
      if ($lines[$i] =~ /^func (?:\([^)]+\)\s+)?(\w+)\(/) {
        push @decls, { pkg=>$pkg, sym=>$1, path=>$path, line=>$i+1, import=>$import_path };
      }
    }
  }
}

sub find_files {
  my ($d, $out) = @_;
  opendir my $dh, $d or return;
  while (my $e = readdir $dh) {
    next if $e eq "." or $e eq "..";
    my $p = "$d/$e";
    if (-d $p) { find_files($p, $out) }
    else { push @$out, $p }
  }
}

# read all non-test go files
my @all_files;
find_files($root, \@all_files);
@all_files = grep { /\.go$/ && !/_test\.go$/ } @all_files;

# For each decl, count files that call pkg.Sym or just Sym if unique exported in that import
my %fanin; # key path:line:sym -> {count=>, callers=>[]}

for my $d (@decls) {
  my $qpkg = quotemeta($d->{pkg});
  my $qsym = quotemeta($d->{sym});
  my $pattern_pkg = qr/\b$qpkg\.$qsym\s*\(/;
  my $pattern_bare = qr/\b$qsym\s*\(/;
  my %caller_files;
  for my $f (@all_files) {
    next if $f eq $d->{path}; # skip self for bare? keep for methods called internally
    open my $fh, "<", $f or next;
    local $/; my $content = <$fh>; close $fh;
    # check if file imports this package
    my $imports_pkg = ($content =~ /\Q$d->{import}\E/);
    my $matched = 0;
    if ($imports_pkg && $content =~ /$pattern_pkg/g) {
      $matched = () = $content =~ /$pattern_pkg/g;
    } elsif (!$imports_pkg) {
      # unqualified only if unlikely collision - skip bare for safety unless only internal pkg
    }
    # also count bare sym if file imports package under alias - already covered by pkg.sym
    # count bare calls in same package file tree
    if ($imports_pkg) {
       my $bare = () = $content =~ /(?<!\.)\b$qsym\s*\(/g;
       # subtract pkg.sym matches already counted? count total call sites
       my $total = () = $content =~ /(?:\b$qpkg\.)?\b$qsym\s*\(/g;
       # only if imports package
       if ($total > 0) {
         $caller_files{$f} += $total;
       }
    }
  }
  my $key = "$d->{path}:$d->{line}:$d->{sym}";
  $fanin{$key} = { decl=>$d, sites=>\%caller_files, total=>0 };
  for (values %caller_files) { $fanin{$key}{total} += $_ }
  $fanin{$key}{file_count} = scalar keys %caller_files;
}

my @ranked = sort { $b->{file_count} <=> $a->{file_count} || $b->{total} <=> $a->{total} } values %fanin;
for my $i (0..24) {
  my $r = $ranked[$i]; last unless $r;
  my $d = $r->{decl};
  my $rel = $d->{path}; $rel =~ s|^\Q$root/\E||;
  printf "%d files / %d calls\t%s.%s\t%s:%d\n", $r->{file_count}, $r->{total}, $d->{pkg}, $d->{sym}, $rel, $d->{line};
}
print "Total decls: ", scalar(@decls), "\n";
'

